"""
Utilities for visualizing vectors and covariances on matplotlib 3d plots.

This functionality is provided for visualizing the results of the example code.
Except for the functions :func:`plot_s2_tangent`, :func:`plot_s2_ellipse`,
:func:`plot_ellipsoid_plane_intersection`, the code has been generated by Claude Fable 5.
While we have visually inspected the results for correctness, the math used for these
visualizations is unchecked. Extra care should thus be taken when those functions are used.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, cast

import numpy as np
from matplotlib.patches import FancyArrowPatch
from mpl_toolkits.mplot3d import proj3d
from mpl_toolkits.mplot3d.art3d import Line3D, Line3DCollection, Poly3DCollection

from pglfd.geom import s2
from pglfd.geom.so3 import quaternion_to_rotmat
from pglfd.visualization.util import ellipse_points, ellipsoid_axes_from_cov, ellipsoid_plane_intersection, ellipsoid_points

if TYPE_CHECKING:
    from matplotlib.pyplot import plt
    from mpl_toolkits.mplot3d.axes3d import Axes3D


class Arrow3D(FancyArrowPatch):
    """A FancyArrowPatch that projects a 3D start/end point pair onto a 3D axes."""

    def __init__(self, start: np.ndarray, end: np.ndarray, *args: Any, **kwargs: Any) -> None:
        """
        Create an arrow from ``start`` to ``end`` (3D points); remaining arguments go to FancyArrowPatch.

        :param start: ``(3)`` Start of arrow.
        :param end: ``(3)`` End of arrow.
        """
        super().__init__((0, 0), (0, 0), *args, **kwargs)
        self._xyz = (start, end)

    def do_3d_projection(self, renderer: Any = None) -> float:  # noqa:  ARG002
        """Project the stored 3D points into 2D display space and return the minimum depth."""
        (x0, y0, z0), (x1, y1, z1) = self._xyz
        xs, ys, zs = proj3d.proj_transform((x0, x1), (y0, y1), (z0, z1), self.axes.M)
        self.set_positions((xs[0], ys[0]), (xs[1], ys[1]))
        return np.min(zs)


def plot_arrow(
    ax: Axes3D,
    start: np.ndarray,
    end: np.ndarray,
    color: Any = "k",
    label: str | None = None,
    lw: float = 2,
    mutation_scale: float = 15,
) -> Arrow3D:
    """
    Draw an arrow from ``start`` to ``end`` on a 3D axes.

    :param ax: Axes to draw the arrow onto.
    :param start: ``(3)`` Start of arrow.
    :param end: ``(3)`` End of arrow.
    :param color: Color of the arrow.
    :param label: Label for the arrow.
    :param lw: Line width of the arrow.
    :param mutation_scale: Mutation scale of the arrow.
    :return: The arrow.
    """
    arrow = Arrow3D(start, end, mutation_scale=mutation_scale, lw=lw, arrowstyle="-|>", color=color)
    ax.add_artist(arrow)
    if label is not None:
        ax.text(*(end * 1.08), label, color=color, fontsize=12)
    return arrow


def plot_s2_tangent(
    ax: plt.Axes,
    pt: np.ndarray,
    vec: np.ndarray,
    color: Any = "k",
    label: str | None = None,
    lw: float = 2,
    mutation_scale: float = 15,
) -> Arrow3D:
    """
    Plot a tangent vector on S2.

    :param ax: Axes to plot onto.
    :param pt: The tangent basis on S2.
    :param vec: The tangent vector at ``pt``.
    :param color: The plot color.
    :param label: Label for the arrow.
    :param lw: Line width of the arrow.
    :param mutation_scale: Mutation scale of the arrow.
    :return: The arrow.
    """
    vec_s2 = np.zeros(3)
    vec_s2[:2] = vec
    return plot_arrow(ax, pt, pt + s2.multiply(pt, vec_s2), color=color, label=label, lw=lw, mutation_scale=mutation_scale)


def plot_coordinate_system(
    ax: Axes3D,
    origin: np.ndarray | None = None,
    scaling: float = 1.0,
    labels: str | None = "xyz",
    colors: tuple[str, str, str] = ("tab:red", "tab:green", "tab:blue"),
) -> None:
    """
    Draw arrows for the ``x``, ``y``, ``z`` axes of a coordinate system.

    :param ax: Axes to plot onto.
    :param origin: ``(7)`` The coordinate system as ``(x, y, z, qx, qy, qz, qw)``.
    :param scaling: Length of the vectors.
    :param labels: Labels of the vectors.
    :param colors: Colors of the vectors.
    """
    if origin is None:
        origin = np.array([0, 0, 0, 0, 0, 0, 1.0])

    if labels is None:
        labels = [None, None, None]  # type: ignore[assignment]

    for e, lab, col in zip(quaternion_to_rotmat(origin[3:]).T, labels, colors, strict=True):  # type: ignore[arg-type]
        plot_arrow(ax, origin[:3], origin[:3] + scaling * e, color=col, label=lab, mutation_scale=15 * scaling)


def plot_ellipse(
    ax: Axes3D,
    center: np.ndarray,
    f1: np.ndarray,
    f2: np.ndarray,
    n_points: int = 200,
    *,
    use_poly: bool = False,
    color: str | list = "k",
    **plot_kwargs: Any,
) -> Poly3DCollection | list[Line3D]:
    """
    Plot a 3D ellipse given by its center and half-axis vectors ``f1``, ``f2``.

    :param ax: Axes to plot onto.
    :param center: Origin of the ellipse.
    :param f1: First half-axis.
    :param f2: Second half-axis.
    :param n_points: Number of points to use when drawing using points.
    :param use_poly: Use a filled polygone instead of points to plot.
    :param color: The plot color.
    :return: The plotted ellipse.
    """
    pts = ellipse_points(center, f1, f2, n_points)
    kwargs: dict[str, Any] = {"lw": 3}
    kwargs.update(plot_kwargs)
    if use_poly:
        poly = Poly3DCollection([pts.T], facecolors=color)
        return ax.add_collection3d(poly)
    return ax.plot(pts[0], pts[1], pts[2], color=color, **kwargs)


def plot_s2_ellipse(
    ax: plt.Axes,
    pt: np.ndarray,
    cov: np.ndarray,
    n_points: int = 200,
    *,
    use_poly: bool = False,
    color: str | list = "k",
) -> Poly3DCollection | list[Line3D]:
    """
    Plot a covariance on S2.

    :param ax: Axes to plot onto.
    :param pt: The tangent basis on S2.
    :param cov: The covariance at ``pt``.
    :param n_points: Number of points to use when drawing using points.
    :param use_poly: Use a filled polygone instead of points to plot.
    :param color: The plot color.
    :return: The plotted ellipse.
    """
    eigenvalues, eigenvectors = np.linalg.eig(cov)
    eigenvectors = eigenvectors[:, [1, 0]]
    eigenvalues = eigenvalues[[1, 0]]

    radii = np.sqrt(eigenvalues)
    f1 = np.zeros(3)
    f2 = np.zeros(3)
    f1[:2] = eigenvectors[0] * radii[0]
    f2[:2] = eigenvectors[1] * radii[1]
    f1 = s2.multiply(pt, f1)
    f2 = s2.multiply(pt, f2)
    return plot_ellipse(ax, pt, f2, f1, n_points=n_points, color=color, use_poly=use_poly)


def plot_ellipsoid(
    ax: Axes3D,
    center: np.ndarray,
    cov: np.ndarray,
    nstd: float = 1.0,
    n_u: int = 40,
    n_v: int = 30,
    *,
    plot_axes: bool = False,
    wireframe: bool = False,
    **surface_kwargs: Any,
) -> Poly3DCollection | Line3DCollection:
    """
    Plot the ellipsoid defined by its center and a 3x3 covariance matrix.

    :param ax: Axes to plot onto.
    :param center: Origin of the covariance.
    :param cov: The covariance to plot.
    :param nstd: Standard deviation scaler.
    :param n_u: Number of points to plot along the azimuth coordinate.
    :param n_v: Number of points to plot along the polar coordinate.
    :param plot_axes: Plot the three half-axes as arrows.
    :param wireframe: Draw a wireframe instead of a shaded surface.
    :return: The plotted ellipsoid.
    """
    radii, R = ellipsoid_axes_from_cov(cov, nstd)
    pts = ellipsoid_points(center, radii, R, n_u, n_v)

    kwargs: dict[str, Any]
    if wireframe:
        # ~24 meridians and ~16 parallels, independent of the sampling density
        kwargs = {
            "rstride": max(1, (n_u - 1) // 24),
            "cstride": max(1, (n_v - 1) // 16),
            "color": "cornflowerblue",
            "alpha": 0.6,
            "linewidth": 0.6,
            "antialiased": True,
        }
        kwargs.update(surface_kwargs)
        surf = ax.plot_wireframe(pts[0], pts[1], pts[2], **kwargs)
    else:
        kwargs = {
            "rstride": 1,
            "cstride": 1,
            "color": "cornflowerblue",
            "alpha": 0.25,
            "linewidth": 0,
            "antialiased": True,
        }
        kwargs.update(surface_kwargs)
        surf = ax.plot_surface(pts[0], pts[1], pts[2], **kwargs)

    if plot_axes:
        for i, col in enumerate(("tab:red", "tab:green", "tab:blue")):
            plot_arrow(ax, center, center + radii[i] * R[:, i], color=col, lw=1.5)

    return surf


def plot_ellipsoid_plane_intersection(
    ax: Axes3D,
    center: np.ndarray,
    cov: np.ndarray,
    n: np.ndarray,
    nstd: float = 1.0,
    n_points: int = 200,
    *,
    use_poly: bool = False,
    color: str | list = "k",
    **plot_kwargs: Any,
) -> Poly3DCollection:
    """
    Plot the ellipse defined by the intersection of an ellipsoid with a plane.

    :param ax: Axes to plot onto.
    :param center: Origin of the covariance.
    :param cov: The covariance to plot.
    :param n: Normal vector of the plane going through the center of the ellipsoid.
    :param nstd: Standard deviation scaler.
    :param n_points: Number of points to use when drawing using points.
    :param use_poly: Use a filled polygone instead of points to plot.
    :param color: The plot color.
    :return: The plotted ellipse.
    """
    ell_center, f1, f2 = ellipsoid_plane_intersection(center, cov, n, 0, nstd)
    return plot_ellipse(
        ax,
        cast("np.ndarray", ell_center),
        cast("np.ndarray", f1),
        cast("np.ndarray", f2),
        n_points,
        use_poly=use_poly,
        color=color,
        **plot_kwargs,
    )
